package orm

import (
	"errors"
	"fmt"
	"go/format"
	"strings"
	"unicode"
)

// EmitParams describes one generation run for the emitter.
type EmitParams struct {
	PackageName string // destination package name
	SourceName  string // source package name, which qualifies model types
	SourcePath  string // source package import path
	Tables      []Table
}

// Import paths written into generated files.
const (
	runtimeImport = "github.com/go-kanna/kanna/orm"
	scopeImport   = "github.com/go-kanna/kanna/orm/scope"
)

// Emit renders the query file for the given tables as gofmt-formatted source.
func Emit(p EmitParams) ([]byte, error) {
	if len(p.Tables) == 0 {
		return nil, errors.New("no tables to emit")
	}

	f := newFileEmit(p)

	var b strings.Builder
	b.WriteString("// Code generated by kanna. DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package %s\n\n", p.PackageName)
	f.writeImports(&b)

	for _, t := range p.Tables {
		f.writeTable(&b, t)
	}

	src, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("gofmt: %w", err)
	}
	return src, nil
}

type importEntry struct {
	Alias string // empty means the last path segment is used as-is
	Path  string
}

// relEmit is a Relation with the names the emitter writes, qualified for the
// destination file.
type relEmit struct {
	Relation

	TargetTypeQ   string // e.g. "model.Post" or "amodel.Account"
	TargetFactory string // e.g. "Posts" or "aquery.Accounts"
	Preloader     string // e.g. "preloadUserPosts"
	ParentPKField string // the parent's primary key Go field, e.g. "ID"
}

type fileEmit struct {
	p             EmitParams
	hasRelations  bool
	hasTimestamps bool
	extraImports  []importEntry
	seenImports   map[string]bool
	rels          map[string][]relEmit
}

func newFileEmit(p EmitParams) *fileEmit {
	f := &fileEmit{
		p:           p,
		seenImports: map[string]bool{},
		rels:        make(map[string][]relEmit, len(p.Tables)),
	}

	for _, t := range p.Tables {
		for _, field := range t.Fields {
			if field.CreatedAt || field.UpdatedAt {
				f.hasTimestamps = true
			}
		}
		if len(t.Relations) > 0 {
			f.hasRelations = true
		}
		for _, r := range t.Relations {
			f.rels[t.Name] = append(f.rels[t.Name], f.resolve(t, r))
		}
	}

	return f
}

// resolve qualifies a relation's type and factory for the destination file,
// collecting whatever imports that takes.
func (f *fileEmit) resolve(t Table, r Relation) relEmit {
	re := relEmit{
		Relation:      r,
		TargetTypeQ:   f.p.SourceName + "." + r.TargetType,
		TargetFactory: factoryName(r.TargetType),
		Preloader:     preloaderName(t, r),
		ParentPKField: t.PK().Name,
	}

	if r.TargetPkgPath == "" {
		return re
	}

	alias := resolveAlias(r.TargetPkgPath, f.p.SourcePath)
	re.TargetTypeQ = alias + "." + r.TargetType
	f.addImport(r.TargetPkgPath, alias)

	// The target's factory lives in its own query package, assumed to sit
	// next to its model package under the same name as this destination.
	extQuery := replaceLastSegment(r.TargetPkgPath, f.p.PackageName)
	destQuery := replaceLastSegment(f.p.SourcePath, f.p.PackageName)
	if extQuery != destQuery {
		queryAlias := resolveAlias(extQuery, destQuery)
		re.TargetFactory = queryAlias + "." + re.TargetFactory
		f.addImport(extQuery, queryAlias)
	}

	return re
}

func (f *fileEmit) addImport(path, alias string) {
	if f.seenImports[path] {
		return
	}
	f.seenImports[path] = true

	entry := importEntry{Path: path}
	if parts := strings.Split(path, "/"); alias != parts[len(parts)-1] {
		entry.Alias = alias
	}
	f.extraImports = append(f.extraImports, entry)
}

func (f *fileEmit) writeImports(b *strings.Builder) {
	b.WriteString("import (\n")
	if f.hasRelations {
		b.WriteString("\t\"context\"\n")
	}
	b.WriteString("\t\"database/sql\"\n")
	if f.hasTimestamps {
		b.WriteString("\t\"time\"\n")
	}
	b.WriteString("\n")
	fmt.Fprintf(b, "\t%q\n", runtimeImport)
	if f.hasRelations {
		fmt.Fprintf(b, "\t%q\n", scopeImport)
	}
	fmt.Fprintf(b, "\t%q\n", f.p.SourcePath)
	for _, e := range f.extraImports {
		if e.Alias != "" {
			fmt.Fprintf(b, "\t%s %q\n", e.Alias, e.Path)
		} else {
			fmt.Fprintf(b, "\t%q\n", e.Path)
		}
	}
	b.WriteString(")\n\n")
}

// tableNames bundles the identifiers generated for one table.
type tableNames struct {
	Type         string
	Factory      string
	ColumnsVar   string
	Scan         string
	ColVal       string
	SetPK        string
	SetCreatedAt string
	SetUpdatedAt string
}

func names(srcName string, t Table) tableNames {
	factory := factoryName(t.Name)
	return tableNames{
		Type:         srcName + "." + t.Name,
		Factory:      factory,
		ColumnsVar:   unexportedName(factory + "Columns"),
		Scan:         unexportedName("scan" + t.Name),
		ColVal:       unexportedName(t.Name + "ColumnValuePairs"),
		SetPK:        unexportedName("set" + t.Name + "PK"),
		SetCreatedAt: unexportedName("set" + t.Name + "CreatedAt"),
		SetUpdatedAt: unexportedName("set" + t.Name + "UpdatedAt"),
	}
}

// preloaderName is the identifier of the preloader emitted for r.
func preloaderName(t Table, r Relation) string {
	return unexportedName("preload" + t.Name + r.FieldName)
}

// emittedNames lists every identifier Emit may declare for tables, for the
// clash guard. It deliberately over-approximates — a setter the emitter ends
// up not writing is still reserved — so the guard cannot drift when the
// emitter's conditions change.
func emittedNames(tables []Table) []string {
	var out []string
	for _, t := range tables {
		n := names("", t)
		out = append(out, n.Factory, n.ColumnsVar, n.Scan, n.ColVal, n.SetPK, n.SetCreatedAt, n.SetUpdatedAt)
		for _, r := range t.Relations {
			out = append(out, preloaderName(t, r))
		}
	}
	return out
}

func (f *fileEmit) writeTable(b *strings.Builder, t Table) {
	n := names(f.p.SourceName, t)
	rels := f.rels[t.Name]
	created, updated := timestampFields(t)

	f.writeFactory(b, t, n, rels, created, updated)
	f.writeColumnsVar(b, t, n)
	f.writeScan(b, t, n, rels)
	f.writeColVal(b, t, n)
	f.writeSetPK(b, t, n)
	f.writeTimestampSetters(b, n, created, updated)
	for _, r := range rels {
		f.writePreloader(b, n, r)
	}
}

func timestampFields(t Table) (created, updated []Field) {
	for _, field := range t.Fields {
		if field.CreatedAt {
			created = append(created, field)
		}
		if field.UpdatedAt {
			updated = append(updated, field)
		}
	}
	return created, updated
}

func (f *fileEmit) writeFactory(b *strings.Builder, t Table, n tableNames, rels []relEmit, created, updated []Field) {
	pk := t.PK()
	setPK := "nil"
	if pk.IntKind {
		setPK = n.SetPK
	}

	fmt.Fprintf(b, "// %s returns a new Query for the %s table.\n", n.Factory, t.TableName)
	fmt.Fprintf(b, "func %s(db orm.Querier) *orm.Query[%s] {\n", n.Factory, n.Type)

	plain := len(rels) == 0 && len(created) == 0 && len(updated) == 0
	lead := "\tq :="
	if plain {
		lead = "\treturn"
	}
	fmt.Fprintf(b, "%s orm.NewQuery[%s](\n", lead, n.Type)
	fmt.Fprintf(b, "\t\tdb, orm.ResolveTableName[%s](%q), %s, %q,\n", n.Type, t.TableName, n.ColumnsVar, pk.Column)
	fmt.Fprintf(b, "\t\t%s, %s, %s,\n", n.Scan, n.ColVal, setPK)
	if plain {
		b.WriteString("\t)\n}\n\n")
		return
	}
	b.WriteString("\t)\n")

	for _, r := range rels {
		if r.Kind != "many_to_many" {
			targetCol, sourceCol := r.ForeignKey, pk.Column
			if r.Kind == "belongs_to" {
				targetCol, sourceCol = r.TargetPKColumn, r.ForeignKey
			}
			fmt.Fprintf(b, "\tq.RegisterJoin(%q, orm.JoinConfig{\n", r.FieldName)
			fmt.Fprintf(b, "\t\tTargetTable: orm.ResolveTableName[%s](%q), TargetColumn: %q,\n",
				r.TargetTypeQ, r.TargetTableName, targetCol)
			fmt.Fprintf(b, "\t\tSourceTable: orm.ResolveTableName[%s](%q), SourceColumn: %q,\n",
				n.Type, t.TableName, sourceCol)
			if r.JoinScan != nil {
				b.WriteString("\t\tSelectColumns: []string{")
				for i, jf := range r.JoinScan.Fields {
					if i > 0 {
						b.WriteString(", ")
					}
					fmt.Fprintf(b, "%q", jf.Column)
				}
				b.WriteString("},\n")
			}
			b.WriteString("\t})\n")
		}
		fmt.Fprintf(b, "\tq.RegisterPreloader(%q, %s)\n", r.FieldName, r.Preloader)
	}

	if len(created) > 0 || len(updated) > 0 {
		b.WriteString("\tq.RegisterTimestamps(\n")
		writeTimestampArgs(b, created, n.SetCreatedAt)
		writeTimestampArgs(b, updated, n.SetUpdatedAt)
		b.WriteString("\t)\n")
	}

	b.WriteString("\treturn q\n}\n\n")
}

func writeTimestampArgs(b *strings.Builder, fields []Field, setter string) {
	if len(fields) == 0 {
		b.WriteString("\t\tnil,\n\t\tnil,\n")
		return
	}
	b.WriteString("\t\t[]string{")
	for i, field := range fields {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(b, "%q", field.Column)
	}
	b.WriteString("},\n")
	fmt.Fprintf(b, "\t\t%s,\n", setter)
}

func (f *fileEmit) writeColumnsVar(b *strings.Builder, t Table, n tableNames) {
	fmt.Fprintf(b, "var %s = []string{", n.ColumnsVar)
	for i, field := range t.Fields {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(b, "%q", field.Column)
	}
	b.WriteString("}\n\n")
}

func (f *fileEmit) writeScan(b *strings.Builder, t Table, n tableNames, rels []relEmit) {
	fmt.Fprintf(b, "func %s(rows *sql.Rows) (%s, error) {\n", n.Scan, n.Type)
	b.WriteString("\tcols, _ := rows.Columns()\n")
	fmt.Fprintf(b, "\tvar v %s\n", n.Type)
	for _, r := range rels {
		if r.JoinScan != nil && r.IsPointer {
			fmt.Fprintf(b, "\tvar joinScan%sPK %s\n", r.FieldName, r.JoinScan.NullType)
			fmt.Fprintf(b, "\tvar joinScan%s %s\n", r.FieldName, r.TargetTypeQ)
		}
	}
	b.WriteString("\tdest := make([]any, len(cols))\n")
	b.WriteString("\tfor i, col := range cols {\n")
	b.WriteString("\t\tswitch col {\n")
	for _, field := range t.Fields {
		fmt.Fprintf(b, "\t\tcase %q:\n", field.Column)
		fmt.Fprintf(b, "\t\t\tdest[i] = &v.%s\n", field.Name)
	}
	for _, r := range rels {
		if r.JoinScan == nil {
			continue
		}
		for _, jf := range r.JoinScan.Fields {
			fmt.Fprintf(b, "\t\tcase \"%s__%s\":\n", r.FieldName, jf.Column)
			switch {
			case r.IsPointer && jf.PrimaryKey:
				fmt.Fprintf(b, "\t\t\tdest[i] = &joinScan%sPK\n", r.FieldName)
			case r.IsPointer:
				fmt.Fprintf(b, "\t\t\tdest[i] = &joinScan%s.%s\n", r.FieldName, jf.Name)
			default:
				fmt.Fprintf(b, "\t\t\tdest[i] = &v.%s.%s\n", r.FieldName, jf.Name)
			}
		}
	}
	b.WriteString("\t\tdefault:\n\t\t\tdest[i] = new(any)\n\t\t}\n\t}\n")
	b.WriteString("\terr := rows.Scan(dest...)\n")
	for _, r := range rels {
		if r.JoinScan == nil || !r.IsPointer {
			continue
		}
		fmt.Fprintf(b, "\tif joinScan%sPK.Valid {\n", r.FieldName)
		fmt.Fprintf(b, "\t\tjoinScan%s.%s = %s(joinScan%sPK%s)\n",
			r.FieldName, r.JoinScan.PK.Name, r.JoinScan.PK.GoType, r.FieldName, r.JoinScan.NullField)
		fmt.Fprintf(b, "\t\tv.%s = &joinScan%s\n", r.FieldName, r.FieldName)
		b.WriteString("\t}\n")
	}
	b.WriteString("\treturn v, err\n}\n\n")
}

func (f *fileEmit) writeColVal(b *strings.Builder, t Table, n tableNames) {
	fmt.Fprintf(b, "func %s(v *%s, includesPK bool) ([]string, []any) {\n", n.ColVal, n.Type)
	b.WriteString("\tif includesPK {\n")
	writeColValReturn(b, t.Fields)
	b.WriteString("\t}\n")
	var nonPK []Field
	for _, field := range t.Fields {
		if !field.PrimaryKey {
			nonPK = append(nonPK, field)
		}
	}
	writeColValReturn(b, nonPK)
	b.WriteString("}\n\n")
}

func writeColValReturn(b *strings.Builder, fields []Field) {
	b.WriteString("\treturn []string{")
	for i, field := range fields {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(b, "%q", field.Column)
	}
	b.WriteString("},\n\t\t[]any{")
	for i, field := range fields {
		if i > 0 {
			b.WriteString(", ")
		}
		fmt.Fprintf(b, "v.%s", field.Name)
	}
	b.WriteString("}\n")
}

func (f *fileEmit) writeSetPK(b *strings.Builder, t Table, n tableNames) {
	pk := t.PK()
	if !pk.IntKind {
		return
	}
	fmt.Fprintf(b, "func %s(v *%s, id int64) {\n", n.SetPK, n.Type)
	fmt.Fprintf(b, "\tv.%s = %s(id)\n", pk.Name, pk.GoType)
	b.WriteString("}\n\n")
}

func (f *fileEmit) writeTimestampSetters(b *strings.Builder, n tableNames, created, updated []Field) {
	if len(created) > 0 {
		fmt.Fprintf(b, "func %s(v *%s, now time.Time) {\n", n.SetCreatedAt, n.Type)
		for _, field := range created {
			if strings.HasPrefix(field.GoType, "*") {
				fmt.Fprintf(b, "\tif v.%s == nil {\n\t\tv.%s = &now\n\t}\n", field.Name, field.Name)
			} else {
				fmt.Fprintf(b, "\tif v.%s.IsZero() {\n\t\tv.%s = now\n\t}\n", field.Name, field.Name)
			}
		}
		b.WriteString("}\n\n")
	}
	if len(updated) > 0 {
		fmt.Fprintf(b, "func %s(v *%s, now time.Time) {\n", n.SetUpdatedAt, n.Type)
		for _, field := range updated {
			if strings.HasPrefix(field.GoType, "*") {
				fmt.Fprintf(b, "\tv.%s = &now\n", field.Name)
			} else {
				fmt.Fprintf(b, "\tv.%s = now\n", field.Name)
			}
		}
		b.WriteString("}\n\n")
	}
}

func (f *fileEmit) writePreloader(b *strings.Builder, n tableNames, r relEmit) {
	fmt.Fprintf(b, "func %s(ctx context.Context, db orm.Querier, results []%s) error {\n", r.Preloader, n.Type)
	b.WriteString("\tif len(results) == 0 {\n\t\treturn nil\n\t}\n")

	switch r.Kind {
	case "has_many":
		writeCollectPKs(b, r)
		fmt.Fprintf(b, "\trelated, err := %s(db).Scopes(scope.In(%q, ids)).All(ctx)\n",
			r.TargetFactory, r.ForeignKey)
		b.WriteString("\tif err != nil {\n\t\treturn err\n\t}\n")
		fmt.Fprintf(b, "\tbyFK := make(map[%s][]%s)\n", r.KeyType, r.TargetTypeQ)
		b.WriteString("\tfor _, r := range related {\n")
		if r.FKIsPointer {
			fmt.Fprintf(b, "\t\tif r.%s != nil {\n", r.ForeignKeyField)
			fmt.Fprintf(b, "\t\t\tbyFK[*r.%s] = append(byFK[*r.%s], r)\n", r.ForeignKeyField, r.ForeignKeyField)
			b.WriteString("\t\t}\n")
		} else {
			fmt.Fprintf(b, "\t\tbyFK[r.%s] = append(byFK[r.%s], r)\n", r.ForeignKeyField, r.ForeignKeyField)
		}
		b.WriteString("\t}\n")
		b.WriteString("\tfor i := range results {\n")
		fmt.Fprintf(b, "\t\tresults[i].%s = byFK[results[i].%s]\n", r.FieldName, r.ParentPKField)
		b.WriteString("\t}\n\treturn nil\n")

	case "has_one":
		writeCollectPKs(b, r)
		fmt.Fprintf(b, "\trelated, err := %s(db).Scopes(scope.In(%q, ids)).All(ctx)\n",
			r.TargetFactory, r.ForeignKey)
		b.WriteString("\tif err != nil {\n\t\treturn err\n\t}\n")
		if r.IsPointer {
			fmt.Fprintf(b, "\tbyFK := make(map[%s]*%s)\n", r.KeyType, r.TargetTypeQ)
			b.WriteString("\tfor i := range related {\n")
			if r.FKIsPointer {
				fmt.Fprintf(b, "\t\tif related[i].%s != nil {\n", r.ForeignKeyField)
				fmt.Fprintf(b, "\t\t\tbyFK[*related[i].%s] = &related[i]\n", r.ForeignKeyField)
				b.WriteString("\t\t}\n")
			} else {
				fmt.Fprintf(b, "\t\tbyFK[related[i].%s] = &related[i]\n", r.ForeignKeyField)
			}
			b.WriteString("\t}\n")
		} else {
			fmt.Fprintf(b, "\tbyFK := make(map[%s]%s)\n", r.KeyType, r.TargetTypeQ)
			b.WriteString("\tfor _, r := range related {\n")
			if r.FKIsPointer {
				fmt.Fprintf(b, "\t\tif r.%s != nil {\n", r.ForeignKeyField)
				fmt.Fprintf(b, "\t\t\tbyFK[*r.%s] = r\n", r.ForeignKeyField)
				b.WriteString("\t\t}\n")
			} else {
				fmt.Fprintf(b, "\t\tbyFK[r.%s] = r\n", r.ForeignKeyField)
			}
			b.WriteString("\t}\n")
		}
		b.WriteString("\tfor i := range results {\n")
		fmt.Fprintf(b, "\t\tresults[i].%s = byFK[results[i].%s]\n", r.FieldName, r.ParentPKField)
		b.WriteString("\t}\n\treturn nil\n")

	case "many_to_many":
		writeCollectPKs(b, r)
		fmt.Fprintf(b, "\tpairs, err := orm.QueryJoinTable[%s, %s]( //nolint:lll\n", r.KeyType, r.KeyType)
		fmt.Fprintf(b, "\t\tctx, db, %q, %q, %q, ids,\n", r.JoinTable, r.ForeignKey, r.References)
		b.WriteString("\t)\n")
		b.WriteString("\tif err != nil {\n\t\treturn err\n\t}\n")
		b.WriteString("\ttargetIDs := orm.UniqueTargets(pairs)\n")
		fmt.Fprintf(b, "\trelated, err := %s(db).Scopes(scope.In(%q, targetIDs)).All(ctx)\n",
			r.TargetFactory, r.TargetPKColumn)
		b.WriteString("\tif err != nil {\n\t\treturn err\n\t}\n")
		fmt.Fprintf(b, "\tbyPK := make(map[%s]%s)\n", r.KeyType, r.TargetTypeQ)
		b.WriteString("\tfor _, r := range related {\n")
		fmt.Fprintf(b, "\t\tbyPK[r.%s] = r\n", r.TargetPKField)
		b.WriteString("\t}\n")
		b.WriteString("\tgrouped := orm.GroupBySource(pairs)\n")
		b.WriteString("\tfor i := range results {\n")
		fmt.Fprintf(b, "\t\ttIDs := grouped[results[i].%s]\n", r.ParentPKField)
		fmt.Fprintf(b, "\t\titems := make([]%s, 0, len(tIDs))\n", r.TargetTypeQ)
		b.WriteString("\t\tfor _, tid := range tIDs {\n\t\t\tif v, ok := byPK[tid]; ok {\n")
		b.WriteString("\t\t\t\titems = append(items, v)\n\t\t\t}\n\t\t}\n")
		fmt.Fprintf(b, "\t\tresults[i].%s = items\n", r.FieldName)
		b.WriteString("\t}\n\treturn nil\n")

	default: // belongs_to
		if r.FKIsPointer {
			fmt.Fprintf(b, "\tids := make([]%s, 0, len(results))\n", r.KeyType)
			b.WriteString("\tfor i := range results {\n")
			fmt.Fprintf(b, "\t\tif results[i].%s != nil {\n", r.ForeignKeyField)
			fmt.Fprintf(b, "\t\t\tids = append(ids, *results[i].%s)\n", r.ForeignKeyField)
			b.WriteString("\t\t}\n\t}\n")
		} else {
			fmt.Fprintf(b, "\tids := make([]%s, len(results))\n", r.KeyType)
			b.WriteString("\tfor i := range results {\n")
			fmt.Fprintf(b, "\t\tids[i] = results[i].%s\n", r.ForeignKeyField)
			b.WriteString("\t}\n")
		}
		fmt.Fprintf(b, "\trelated, err := %s(db).Scopes(scope.In(%q, ids)).All(ctx)\n",
			r.TargetFactory, r.TargetPKColumn)
		b.WriteString("\tif err != nil {\n\t\treturn err\n\t}\n")
		if r.IsPointer {
			fmt.Fprintf(b, "\tbyPK := make(map[%s]*%s)\n", r.KeyType, r.TargetTypeQ)
			b.WriteString("\tfor i := range related {\n")
			fmt.Fprintf(b, "\t\tbyPK[related[i].%s] = &related[i]\n", r.TargetPKField)
			b.WriteString("\t}\n")
		} else {
			fmt.Fprintf(b, "\tbyPK := make(map[%s]%s)\n", r.KeyType, r.TargetTypeQ)
			b.WriteString("\tfor _, r := range related {\n")
			fmt.Fprintf(b, "\t\tbyPK[r.%s] = r\n", r.TargetPKField)
			b.WriteString("\t}\n")
		}
		b.WriteString("\tfor i := range results {\n")
		if r.FKIsPointer {
			fmt.Fprintf(b, "\t\tif results[i].%s != nil {\n", r.ForeignKeyField)
			fmt.Fprintf(b, "\t\t\tresults[i].%s = byPK[*results[i].%s]\n",
				r.FieldName, r.ForeignKeyField)
			b.WriteString("\t\t}\n")
		} else {
			fmt.Fprintf(b, "\t\tresults[i].%s = byPK[results[i].%s]\n", r.FieldName, r.ForeignKeyField)
		}
		b.WriteString("\t}\n\treturn nil\n")
	}

	b.WriteString("}\n\n")
}

// writeCollectPKs writes the id collection loop shared by the preloaders that
// key off the parent's primary key.
func writeCollectPKs(b *strings.Builder, r relEmit) {
	fmt.Fprintf(b, "\tids := make([]%s, len(results))\n", r.KeyType)
	b.WriteString("\tfor i := range results {\n")
	fmt.Fprintf(b, "\t\tids[i] = results[i].%s\n", r.ParentPKField)
	b.WriteString("\t}\n")
}

func unexportedName(s string) string {
	if s == "" {
		return s
	}
	runes := []rune(s)
	runes[0] = unicode.ToLower(runes[0])
	return string(runes)
}

// resolveAlias determines the import alias for an external package. When the
// last path segment collides with the source import's, the previous segment
// is prepended to disambiguate.
func resolveAlias(importPath, sourceImport string) string {
	parts := strings.Split(importPath, "/")
	lastSeg := parts[len(parts)-1]

	if sourceImport == "" {
		return lastSeg
	}

	srcParts := strings.Split(sourceImport, "/")
	if lastSeg != srcParts[len(srcParts)-1] {
		return lastSeg
	}

	if len(parts) >= 2 {
		return parts[len(parts)-2] + lastSeg
	}
	return lastSeg
}

// replaceLastSegment swaps the last path segment of an import path:
// ("github.com/foo/model", "query") → "github.com/foo/query".
func replaceLastSegment(importPath, newSeg string) string {
	i := strings.LastIndex(importPath, "/")
	if i < 0 {
		return newSeg
	}
	return importPath[:i+1] + newSeg
}
